/**
 * run-record — the record type of schema id `specstride.run-state/1`, annex E, §E.2.
 *
 * Generated by `scripts/types.mjs` from `schemas/run-record.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface RunRecord {
  /**
   * Schema id
   *
   * Type in words: Text.
   */
  schema: string;
  /**
   * Identifiers and feature slug
   *
   * Type in words: Text.
   */
  runId: string;
  /**
   * Identifiers and feature slug
   *
   * Type in words: Text.
   */
  workspaceId: string;
  /**
   * Identifiers and feature slug
   *
   * Type in words: Text.
   */
  feature: string;
  /**
   * A state of the machine, never a derived condition
   *
   * Type in words: Member of a closed set.
   */
  state: string;
  /**
   * Time of the last transition
   *
   * Type in words: Timestamp, UTC.
   */
  stateSince: string;
  /**
   * Number of the last transition, T1 to T17
   *
   * Type in words: Text.
   */
  transition: string;
  /**
   * The current launch and engine start
   *
   * Type in words: Text.
   */
  launchId: string;
  /**
   * The current launch and engine start
   *
   * Type in words: Text.
   */
  engineStartId: string;
  /**
   * `standalone` or `child`
   *
   * Type in words: Member of a closed set.
   */
  startMode: "standalone" | "child";
  /**
   * `pipeline` or `engine`
   *
   * Type in words: Member of a closed set.
   */
  requestKind: "pipeline" | "engine";
  /**
   * Product version of every engine start of the run
   *
   * Type in words: List of text.
   */
  productVersions: unknown[];
  /**
   * `root` or `supervise`
   *
   * Type in words: Member of a closed set.
   */
  relaunchOwner: "root" | "supervise";
  /**
   * The pinned strategy and its named fields: `loop.strategy`, `loop.level`, `loop.manifest_hash`, and with parallel units the fields `loop.parallel.*`
   *
   * Type in words: Record.
   */
  loop: Record<string, unknown>;
  /**
   * Level in force per role, and `protection` (`prevent` or `detect`)
   *
   * Type in words: Record.
   */
  containment: Record<string, unknown>;
  /**
   * Result of the proof of the form of the `completion` level
   *
   * Type in words: Record.
   */
  criticProof: Record<string, unknown>;
  /**
   * Version of the pattern set of the redactor
   *
   * Type in words: Text.
   */
  redaction: string;
  /**
   * The setting of harness-native memory per role
   *
   * Type in words: Record.
   */
  nativeMemory: Record<string, unknown>;
  /**
   * The caps and budgets in force
   *
   * Type in words: Record.
   */
  caps: Record<string, unknown>;
  /**
   * The parallelism of verification commands in force, when the runtime lowered it below the configured value. In start mode `child` the runtime root copies it from the field of the same name of the terminal record before the next engine start. Where the root synthesized the terminal record, it takes the value `to` of the last event `check.parallelism_lowered` of the run
   *
   * Type in words: Whole number.
   */
  verificationParallelism?: number;
}
